// Generated by bin/dev-write-prod-vendor.py. Do not use full composer --dev autoload.


spl_autoload_register(
	static function ( $class ) {
		$prefixes = array(
			'MatthiasMullie\\Minify\\'         => __DIR__ . '/matthiasmullie/minify/src/',
			'MatthiasMullie\\PathConverter\\' => __DIR__ . '/matthiasmullie/path-converter/src/',
		);
		foreach ( $prefixes as $prefix => $base_dir ) {
			$len = strlen( $prefix );
			if ( 0 !== strncmp( $prefix, $class, $len ) ) {
				continue;
			}
			$relative = substr( $class, $len );
			$file     = $base_dir . str_replace( '\\', '/', $relative ) . '.php';
			if ( is_file( $file ) ) {
				require $file;
			}
			return;
		}
	}
);
